  test("throws a descriptive error when CLERK_JWT_ISSUER_DOMAIN is unset", async () => {
    delete process.env[ENV_KEY];
    vi.resetModules();
    await expect(import("./auth.config")).rejects.toThrow(
      /CLERK_JWT_ISSUER_DOMAIN/,
