import Foundation

// Client configuration. Both values are public (safe to ship in the app
// binary): the Clerk publishable key is client-side by design, and the
// Convex deployment URL is public. Replace both before running.
//
// - clerkPublishableKey: Clerk dashboard -> API keys (pk_test_... / pk_live_...).
// - convexDeploymentUrl: your Convex deployment URL, e.g. https://<name>.convex.cloud
//   (the dev deployment for this project is brilliant-puma-925).
//
// The Convex side also needs a JWT template named "convex" in Clerk, and
// CLERK_JWT_ISSUER_DOMAIN set on the Convex deployment (see convex/auth.config.ts).
enum Config {
    static let clerkPublishableKey = "YOUR_CLERK_PUBLISHABLE_KEY"
    static let convexDeploymentUrl = "YOUR_CONVEX_DEPLOYMENT_URL"
}

import ClerkConvex
import ClerkKit
import ClerkKitUI
import ConvexMobile
import SwiftUI

// Single app-lifetime Convex client, authenticated through Clerk. The
// ClerkConvexAuthProvider watches the Clerk session and fetches the "convex"
// JWT template token on its own -- there is no manual login call to make.
@MainActor
let convex = ConvexClientWithAuth(
    deploymentUrl: Config.convexDeploymentUrl,
    authProvider: ClerkConvexAuthProvider()
)

@main
struct HavenApp: App {
    init() {
        Clerk.configure(publishableKey: Config.clerkPublishableKey)
    }

    var body: some Scene {
        WindowGroup {
            RootView()
                .prefetchClerkImages()
                .environment(Clerk.shared)
        }
    }
}

import Combine
import ConvexMobile
import SwiftUI

// Mirrors the Convex client's auth state into an observable the UI can switch on.
// A subscription error is treated as unauthenticated so the UI never gets stuck
// on the loading spinner.
@MainActor
final class AuthModel: ObservableObject {
    @Published var authState: AuthState<String> = .loading

    init() {
        convex.authState
            .replaceError(with: .unauthenticated)
            .receive(on: DispatchQueue.main)
            .assign(to: &$authState)
    }
}

import ClerkKitUI
import SwiftUI

// Phase 0 smoke test for the Clerk -> Convex authenticated seam.
